# Simulator Masalah Polling Kueri updated_at vs Log Mutation Capture
class PollingExtractionSimulator:
    def __init__(self):
        self.database_state = {
            1: {'val': 'aktif', 'updated_at': 100},
            2: {'val': 'aktif', 'updated_at': 100},
            3: {'val': 'aktif', 'updated_at': 100}
        }
        self.last_sync_time = 90

    def execute_mutations(self):
        # Event 1: Update record 1
        self.database_state[1] = {'val': 'diperbarui', 'updated_at': 105}
        # Event 2: Hard delete record 2 (baris fisik dihapus!)
        del self.database_state[2]

    def run_query_polling(self, current_time):
        # Polling: SELECT * WHERE updated_at > last_sync_time
        extracted = []
        for k, v in self.database_state.items():
            if v['updated_at'] > self.last_sync_time:
                extracted.append((k, v))
        self.last_sync_time = current_time
        return extracted

sim = PollingExtractionSimulator()
print('Kondisi Awal DB:', sim.database_state)
sim.execute_mutations()
polled = sim.run_query_polling(current_time=110)

print('\nHasil Polling Terjadwal (updated_at > 90):')
for r in polled:
    print(f'  - Berhasil Tangkap: ID {r[0]} -> {r[1]}')
print(f'  - Status Record ID 2: HILANG TANPA JEJAK (Hard Delete tidak tertangkap polling!)')
print('Kesimpulan: Polling kueri updated_at buta terhadap operasi penghapusan fisik.')

