# Simulator Konfigurasi Deklaratif & Registrasi Konektor Debezium pada Kafka Connect
class DebeziumConnectorRegistry:
    def __init__(self):
        self.active_connectors = {}

    def register_connector(self, name, config):
        # Validasi field konfigurasi esensial Debezium
        required_keys = ['connector.class', 'database.hostname', 'database.dbname', 'topic.prefix']
        for k in required_keys:
            if k not in config:
                raise ValueError(f'Konfigurasi tidak lengkap: field {k} hilang!')

        self.active_connectors[name] = {
            'status': 'RUNNING',
            'tasks_count': 1,
            'config': config,
            'destination_topic': f"{config['topic.prefix']}.{config['table.include.list']}"
        }
        return self.active_connectors[name]

registry = DebeziumConnectorRegistry()
pg_cdc_config = {
    'connector.class': 'io.debezium.connector.postgresql.PostgresConnector',
    'database.hostname': 'db-primary.prod.internal',
    'database.dbname': 'order_service',
    'database.user': 'debezium_cdc',
    'plugin.name': 'pgoutput',
    'topic.prefix': 'orders_cdc',
    'table.include.list': 'public.orders'
}

deployed = registry.register_connector('order-cdc-connector', pg_cdc_config)
