# Parser & Evaluator Event Envelope CDC Debezium Terstandarisasi
class DebeziumEnvelopeParser:
    @staticmethod
    def process_event(event_payload, consumer_receive_time_ms):
        op = event_payload.get('op')
        source = event_payload.get('source', {})
        commit_time = source.get('ts_ms', 0)
        replication_lag_ms = max(0, consumer_receive_time_ms - commit_time)

        if op == 'c':
            action = 'INSERT DATA BARU'
            data = event_payload.get('after')
        elif op == 'u':
            action = 'UPDATE NILAI KOLOM'
            data = {'sebelum': event_payload.get('before'), 'sesudah': event_payload.get('after')}
        elif op == 'd':
            action = 'HARD DELETE DITANGKAP'
            data = {'terhapus': event_payload.get('before')}
        else:
            action = 'SNAPSHOT READ'
            data = event_payload.get('after')

        return {
            'aksi': action,
            'lsn': source.get('lsn'),
            'tabel': f"{source.get('schema')}.{source.get('table')}",
            'lag_ms': replication_lag_ms,
            'payload': data
        }

# Sampel Event Envelope Debezium (Operasi UPDATE order status)
sample_event = {
    'before': {'order_id': 8841, 'amount': 150.0, 'status': 'PENDING'},
    'after':  {'order_id': 8841, 'amount': 150.0, 'status': 'PAID'},
    'op': 'u',
    'source': {'db': 'prod_shop', 'schema': 'public', 'table': 'orders', 'lsn': 10592834, 'ts_ms': 1700000000000}
}

parsed = DebeziumEnvelopeParser.process_event(sample_event, consumer_receive_time_ms=1700000000185)
print('Hasil Parsing Debezium Event Envelope:')
print(f"  Aksi Deteksi : {parsed['aksi']}")
print(f"  Target Tabel : {parsed['tabel']} | LSN: {parsed['lsn']}")
print(f"  Replikasi Lag: {parsed['lag_ms']} ms")
print(f"  Detail Mutasi: {parsed['payload']['sebelum']['status']} -> {parsed['payload']['sesudah']['status']}")
print('Kesimpulan: Amplop Debezium menyediakan konteks sebelum/sesudah dan metadata audit lengkap.')

# Simulator Pemrosesan Hard Delete & Propagasi Tombstone ke Data Lakehouse
class LakehouseCDCApplier:
    def __init__(self):
        self.lakehouse_table = {}

    def apply_cdc_event(self, key, event):
        if event is None or event.get('op') == 'd':
            # Tangani Hard Delete: Buat penanda tombstone logis di Silver Layer
            if key in self.lakehouse_table:
                self.lakehouse_table[key]['_is_deleted_cdc'] = True
                self.lakehouse_table[key]['_deleted_at_lsn'] = event['source']['lsn'] if event else None
        else:
            # Tangani Insert / Update
            row_data = dict(event['after'])
            row_data['_is_deleted_cdc'] = False
            row_data['_source_lsn'] = event['source']['lsn']
            self.lakehouse_table[key] = row_data

lake = LakehouseCDCApplier()
# Ingesti Insert
lake.apply_cdc_event('U101', {'op': 'c', 'after': {'name': 'Budi', 'tier': 'GOLD'}, 'source': {'lsn': 100}})
lake.apply_cdc_event('U102', {'op': 'c', 'after': {'name': 'Citra', 'tier': 'SILVER'}, 'source': {'lsn': 102}})
print('Tabel Lakehouse Pasca-Insert:', lake.lakehouse_table)

# Ingesti Hard Delete pada U101
delete_event = {'op': 'd', 'before': {'name': 'Budi', 'tier': 'GOLD'}, 'after': None, 'source': {'lsn': 108}}
lake.apply_cdc_event('U101', delete_event)

print('\nTabel Lakehouse Pasca-Penghapusan CDC:')
for uid, data in lake.lakehouse_table.items():
    status = 'TERHAPUS (Tombstone)' if data['_is_deleted_cdc'] else 'AKTIF'
    print(f"  User ID {uid}: {data['name']} -> Status: {status}")
print('Kesimpulan: Tombstone menjaga jejak audit historis tanpa kehilangan rekonsiliasi data.')

# Simulator Single Message Transformation (SMT): Unwrapping Debezium Envelope
class DebeziumSMTUnwrapper:
    @staticmethod
    def transform(record):
        op = record.get('op')
        if op == 'd':
            # Kasus Delete: Kembalikan tombstone dengan flag penanda
            return {'id': record['before']['id'], '__deleted': True}
        else:
            # Kasus Insert / Update: Ekstrak field after murni
            flattened = dict(record.get('after', {}))
            flattened['__deleted'] = False
            return flattened

raw_cdc_envelope = {
    'before': None,
    'after': {'id': 501, 'nama_produk': 'Keyboard Mekanikal', 'harga': 750000},
    'op': 'c',
    'source': {'ts_ms': 1700000000000}
}

unwrapped = DebeziumSMTUnwrapper.transform(raw_cdc_envelope)
print('Payload Mentah Debezium : Envelope kompleks 4-tier')
print('Hasil SMT Unwrapped Payload:', unwrapped)
print('Kesimpulan: SMT menyederhanakan struktur pesan sehingga langsung ramah untuk analitik.')

