# Simulator Deduplikasi CDC Berbasis LSN & Operasi Rekonsiliasi MERGE INTO
class LakehouseMergeSimulator:
    @staticmethod
    def deduplicate_batch(cdc_events):
        # Ambil mutasi dengan LSN tertinggi untuk setiap primary key
        sorted_events = sorted(cdc_events, key=lambda x: x['lsn'], reverse=True)
        deduped = {}
        for e in sorted_events:
            pk = e['id']
            if pk not in deduped:
                deduped[pk] = e
        return list(deduped.values())

    @staticmethod
    def apply_merge(target_table, deduped_events):
        for e in deduped_events:
            pk = e['id']
            op = e['op']
            if op == 'd':
                # Hapus dari tabel
                target_table.pop(pk, None)
            else:
                # Upsert (Insert atau Update)
                target_table[pk] = {'name': e['name'], 'val': e['val'], 'lsn': e['lsn']}
        return target_table

# Batch CDC berisi 3 mutasi pada ID 101 dalam waktu berdekatan
micro_batch = [
    {'id': 101, 'op': 'c', 'name': 'Laptop', 'val': 1000, 'lsn': 500},
    {'id': 101, 'op': 'u', 'name': 'Laptop Gaming', 'val': 1200, 'lsn': 520},
    {'id': 101, 'op': 'u', 'name': 'Laptop Pro', 'val': 1500, 'lsn': 550},
    {'id': 102, 'op': 'c', 'name': 'Mouse', 'val': 50, 'lsn': 510}
]

target = {}
deduped = LakehouseMergeSimulator.deduplicate_batch(micro_batch)
updated_table = LakehouseMergeSimulator.apply_merge(target, deduped)

print(f'Total Event Batch: {len(micro_batch)} -> Pasca-Deduplikasi: {len(deduped)}')
print('Kondisi Akhir Tabel Target Lakehouse:')
for k, v in updated_table.items():
    print(f"  ID {k}: {v['name']} (Harga: ${v['val']}, Versi LSN Terakhir: {v['lsn']})")
print('Kesimpulan: Deduplikasi berbasis LSN menjamin operasi MERGE INTO 100% deterministik.')

# Implementasi Pipeline Lengkap CDC: Ingesti Log -> Kafka Stream -> Buffer -> Sink Parquet
class EndToEndCDCPipelineSimulator:
    def __init__(self):
        self.object_storage_lake = {}
        self.metrics = {'total_captured': 0, 'merged_records': 0}

    def run_pipeline(self, cdc_stream_events):
        self.metrics['total_captured'] = len(cdc_stream_events)

        # 1. Deduplikasi Micro-Batch berdasarkan Primary Key & LSN tertinggi
        sorted_stream = sorted(cdc_stream_events, key=lambda x: x['source']['lsn'], reverse=True)
        deduped = {}
        for e in sorted_stream:
            pk = e['after']['id'] if e['op'] != 'd' else e['before']['id']
            if pk not in deduped:
                deduped[pk] = e

        # 2. Rekonsiliasi ke Object Storage (Simulasi MERGE INTO)
        for pk, event in deduped.items():
            op = event['op']
            if op == 'd':
                self.object_storage_lake.pop(pk, None)
            else:
                self.object_storage_lake[pk] = {
                    'nama': event['after']['nama'],
                    'skor': event['after']['skor'],
                    '_lsn': event['source']['lsn']
                }
        self.metrics['merged_records'] = len(self.object_storage_lake)
        return self.object_storage_lake

# Aliran mutasi streaming dari PostgreSQL WAL
cdc_stream = [
    {'op': 'c', 'after': {'id': 1, 'nama': 'Dataset_A', 'skor': 85}, 'before': None, 'source': {'lsn': 1001}},
    {'op': 'c', 'after': {'id': 2, 'nama': 'Dataset_B', 'skor': 90}, 'before': None, 'source': {'lsn': 1002}},
    {'op': 'u', 'after': {'id': 1, 'nama': 'Dataset_A_v2', 'skor': 95}, 'before': {'id': 1, 'nama': 'Dataset_A', 'skor': 85}, 'source': {'lsn': 1005}},
    {'op': 'd', 'after': None, 'before': {'id': 2, 'nama': 'Dataset_B', 'skor': 90}, 'source': {'lsn': 1008}}
]

pipeline = EndToEndCDCPipelineSimulator()
final_lake = pipeline.run_pipeline(cdc_stream)

print('Audit Pipeline CDC End-to-End:')
print(f"  Total Event Ditangkap  : {pipeline.metrics['total_captured']}")
print(f"  Record Aktif di Storage: {pipeline.metrics['merged_records']}")
print('Status Tabel di Object Storage:')
for k, v in final_lake.items():
    print(f"  - ID {k}: {v['nama']} (Skor: {v['skor']}, LSN: {v['_lsn']})")
print('Kesimpulan: Pipeline CDC sukses menyinkronkan status data secara konsisten dan atomik.')
